using RailwayWebBuilderCore.Enums;

namespace RailwayWebBuilderCore._SiteData.ModelRailways.Layouts;

internal class BluishMoor : LayoutBase
{
    public BluishMoor()
    {
        Name = LayoutNamesEnums.BluishMoor;
        Owner = "Phil Mason, Macclesfield Model Railway Group";
        Description = "Bluish was originally conceived as a test bed for a larger Woodhead based layout, Torside, by members of Macclesfield Model Railway Group, but the layout has taken on a life of its own and is seen here in an extended form. Based on Reddish, near Stockport, and set around 1980, the success of the original Traction Maintenance Depot and the increasing availability of 3mm scale models created the need for more space, hence Bluish Moor. The original shed layout has been added to a wagon works created from a rescaled paper kit which appeared in an early issue of Model Rail. At 1:100 scale, 3mm is a perfect scale for model railways and is amply supported by the 3mm Society and, increasingly, the trade. Track is a combination of Peco H0m and society sleeper base, and control is analogue via Gaugemaster handheld units with elderly H&M motors powering the points. Many of the locomotives are scratchbuilt in Plastikard running on a variety of chassis from Roco, Tillig, Piko and Arnold, though 3D printing is coming to the fore, especially with the offerings from Lincoln Loco Works.";
    }
}
